import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

const exporter = new OBJExporter();

/**
 * Export a single mesh (with its world transform baked in) to an OBJ file.
 */
function exportMeshToOBJ(mesh, filePath) {
    // Clone the mesh so we don't mutate the original scene
    const clone = mesh.clone();

    // Bake the world matrix into the geometry so the OBJ reflects absolute positioning
    mesh.updateWorldMatrix(true, false);
    const geomClone = mesh.geometry.clone();
    geomClone.applyMatrix4(mesh.matrixWorld);

    const tempMesh = new THREE.Mesh(geomClone);
    tempMesh.name = mesh.name;

    const scene = new THREE.Scene();
    scene.add(tempMesh);

    const objString = exporter.parse(scene);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, objString);
}

/**
 * Export a group (with all descendant meshes, world transforms baked) to a single OBJ file.
 */
function exportGroupToOBJ(group, filePath) {
    const scene = new THREE.Scene();

    group.updateWorldMatrix(true, true);
    group.traverse((child) => {
        if (child.isMesh) {
            const geomClone = child.geometry.clone();
            geomClone.applyMatrix4(child.matrixWorld);
            const tempMesh = new THREE.Mesh(geomClone);
            tempMesh.name = child.name;
            scene.add(tempMesh);
        }
    });

    const objString = exporter.parse(scene);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, objString);
}

// --- Main ---

const root = createScene();

// Update all world matrices
root.updateMatrixWorld(true);

const outputBase = '/root/output';
const partMeshesDir = path.join(outputBase, 'part_meshes');
const linksDir = path.join(outputBase, 'links');

fs.mkdirSync(partMeshesDir, { recursive: true });
fs.mkdirSync(linksDir, { recursive: true });

/**
 * Recursively process a group:
 *  - For each direct child that is a Mesh: export it individually to part_meshes/<partName>/
 *  - For each direct child that is a Group: recurse into it (it's a sub-part)
 *  - Export the entire group (all descendant meshes) as a single link OBJ
 */
function processGroup(group, parentPartDir) {
    const partName = group.name;
    const partDir = path.join(partMeshesDir, parentPartDir, partName);
    fs.mkdirSync(partDir, { recursive: true });

    let meshCount = 0;
    let subGroupCount = 0;

    for (const child of group.children) {
        if (child.isMesh) {
            const meshFileName = `${child.name}.obj`;
            const meshFilePath = path.join(partDir, meshFileName);
            exportMeshToOBJ(child, meshFilePath);
            meshCount++;
            console.log(`  Mesh: ${child.name} -> ${meshFilePath}`);
        } else if (child.isGroup || child.isObject3D) {
            // Check if this child has its own children (i.e., it's a sub-group/sub-part)
