 *  - For each direct child that is a Group: recurse into it (it's a sub-part)
 *  - Export the entire group (all descendant meshes) as a single link OBJ
 */
function processGroup(group, parentPartDir) {
    const partName = group.name;
    const partDir = path.join(partMeshesDir, parentPartDir, partName);
    fs.mkdirSync(partDir, { recursive: true });

    let meshCount = 0;
    let subGroupCount = 0;

    for (const child of group.children) {
