        } else if (child.isGroup || child.isObject3D) {
            // Check if this child has its own children (i.e., it's a sub-group/sub-part)
            if (child.children && child.children.length > 0 && child.name) {
                subGroupCount++;
                console.log(`  Sub-group: ${child.name}`);
                processGroup(child, path.join(parentPartDir, partName));
            }
        }
    }

    // Export the entire group as a single link OBJ
    const linkFilePath = path.join(linksDir, `${partName}.obj`);
    exportGroupToOBJ(group, linkFilePath);
    console.log(`Link: ${partName} -> ${linkFilePath}`);

    return { meshCount, subGroupCount };
}

// The root group "ferris_wheel" contains two top-level part groups
console.log(`Root: ${root.name}`);
console.log(`Direct children: ${root.children.map(c => c.name).join(', ')}`);
console.log('---');

for (const child of root.children) {
    if (child.isGroup) {
        console.log(`\nProcessing part: ${child.name}`);
        const stats = processGroup(child, '');
        console.log(`  -> ${stats.meshCount} direct meshes, ${stats.subGroupCount} sub-groups`);
    }
}

